import pandas as pd
import numpy as np
from scipy import stats
import glob

# Load all available experiments
csv_files = ['experiment_1_csv', 'experiment_2_csv', 'experiment_4_csv', 'experiment_5_csv', 'experiment_6_csv', 'experiment_9_csv', 'experiment_11_csv', 'experiment_12_csv']
all_dfs = []
for fname in csv_files:
    try:
        df = pd.read_csv(eval(fname))
        # Keep only rows with chelator dosing info
        if 'do_ChelatorDosing' in df.columns or 'ChelatorDosing' in df.columns or any('helator' in c for c in df.columns):
            all_dfs.append(df)
        elif 'ProductTiter' in df.columns:
            all_dfs.append(df)
    except:
        pass

print(f"Loaded {len(all_dfs)} experiments")
for i, df in enumerate(all_dfs):
    print(f"Experiment {i}: columns={list(df.columns)}, shape={df.shape}")

# Find the chelator column name
chelator_cols = []
for df in all_dfs:
    for c in df.columns:
        if 'helator' in c.lower() or 'chel' in c.lower():
            chelator_cols.append(c)
print(f"\nChelator columns found: {chelator_cols}")
